// One-hot to binary function, used to generate the next state number.
function [2:0] onehot2bin;
    input [2:0] onehot;
    begin
        case (onehot)
            3'b001: onehot2bin = 1;
            3'b010: onehot2bin = 2;
            3'b100: onehot2bin = 3;
            default: onehot2bin = 0;
        endcase
    end
endfunction

// FSM state transition function, used to generate the next state one-hot
// signal.
function [2:0] state_transition;
    input [2:0] state;
    input x;
    begin
        case (state)
            3'b000: state_transition = x ? 3'b001 : 3'b000;
            3'b001: state_transition = x ? 3'b100 : 3'b001;
            3'b010: state_transition = x ? 3'b001 : 3'b010;
            3'b011: state_transition = x ? 3'b010 : 3'b001;
            3'b100: state_transition = x ? 3'b100 : 3'b100;
            default: state_transition = 3'b000;
        endcase
    end
endfunction

// Main module.
module TopModule(input clk, input x, input [2:0] y, output reg Y0, output reg z);
    reg [2:0] state;
    reg [2:0] nextstate;
    always @(posedge clk) begin
        state <= nextstate;
        Y0 <= onehot2bin(nextstate);
        case ({state, x})
            6'b000000: z <= 1'b0;
            6'b001000: z <= 1'b0;
            6'b001001: z <= 1'b0;
            6'b001100: z <= 1'b0;
            6'b010000: z <= 1'b0;
            6'b010001: z <= 1'b0;
            6'b010100: z <= 1'b0;
            6'b010101: z <= 1'b1;
            6'b011000: z <= 1'b1;
            6'b011001: z <= 1'b0;
            6'b011100: z <= 1'b0;
            default: z <= 1'bx;
        endcase
        nextstate <= state_transition(state, x);
    end
